<?php $page_title='Dashboard';require_once __DIR__.'/../includes/admin-header.php';$totalCustomers=(int)db()->query('SELECT COUNT(*) FROM customers')->fetchColumn();$counts=['total'=>0];foreach(status_labels() as $k=>$v)$counts[$k]=0;foreach(db()->query('SELECT status,COUNT(*) n FROM shipments GROUP BY status') as $r){if(isset($counts[$r['status']]))$counts[$r['status']]=$r['n'];$counts['total']+=$r['n'];}$recent=db()->query('SELECT s.*,c.name customer_name FROM shipments s JOIN customers c ON c.id=s.customer_id ORDER BY s.created_at DESC LIMIT 8')->fetchAll();?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Dashboard</h1><p class="text-muted mb-0">Shipment overview</p></div><a href="shipment-add.php" class="btn btn-primary">+ Add Shipment</a></div><div class="row g-3 mb-4"><?php foreach([['Customers',$totalCustomers],['Shipments',$counts['total']],['فرع تركيا',$counts['turkey_branch']],['فرع دبي',$counts['dubai_branch']],['شحن أربيل',$counts['shipping_to_erbil']],['في مخزن أربيل',$counts['erbil_warehouse']],['تم التسليم',$counts['delivered']]] as $x):?><div class="col-6 col-lg-2"><div class="card p-3 h-100"><div class="text-muted small"><?=e($x[0])?></div><div class="stat-number"><?=e($x[1])?></div></div></div><?php endforeach;?></div><div class="card table-card"><div class="p-3 border-bottom"><h2 class="h5 mb-0">Recent Shipments</h2></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Brand / JTR</th><th>Customer</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><small class="text-muted d-block"><?=e($r['brand_name']?:'-')?></small><strong><?=e($r['jtr_number'])?></strong></td><td><?=e($r['customer_name'])?></td><td><?=e($r['shipment_date'])?></td><td><span class="status-badge <?=e(status_class($r['status']))?>"><?=e(status_labels()[$r['status']])?></span></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="4" class="text-center text-muted py-4">No shipments yet.</td></tr><?php endif;?></tbody></table></div></div>
